function siteTrackingFactory() {
  const ROOT = 'luxurysmartapartments.com';
  const KEYS = ['utm_source','utm_medium','utm_campaign','utm_content'];
  const types = {status_new:'booking_confirmation',status_cancelled:'booking_cancellation',status_modified:'booking_modification',house_rules:'house_rules',checkin_guide:'checkin_guide',reminder_checkin:'checkin_reminder',reminder_checkout:'checkout_reminder'};
  function language(value, body) {
    const supplied=String(value||'').toLowerCase().slice(0,2);
    if(['ar','en','fr'].includes(supplied))return supplied;
    const text=String(body||'');
    const existing=text.match(/utm_content=[^\s&<>"']*_(ar|en|fr)(?:[\s&<>"']|$)/i);
    if(existing)return existing[1].toLowerCase();
    const arabic=(text.match(/[\u0600-\u06ff]/g)||[]).length;
    const latin=(text.match(/[a-z]/gi)||[]).length;
    if(arabic>latin)return 'ar';
    if(/[àâçéèêëîïôûùüÿœ]/i.test(text)||/\b(bonjour|cher|chère|votre|réservation|annulation|demain|merci|séjour)\b/i.test(text))return 'fr';
    return 'en';
  }
  function type(value) {
    const v=String(value||'');
    return types[v] || (/^review_followup_[123]$/.test(v)?v:'message');
  }
  function origin(scenario, messageType) {
    const s=String(scenario||'01').padStart(2,'0');
    if(s==='03')return /^reminder_/.test(messageType||'')?'02':/^review_followup_/.test(messageType||'')?'04':'01';
    return ['01','02','04','05','06'].includes(s)?s:'01';
  }
  function decode(s){try{return decodeURIComponent(s.replace(/\+/g,' '));}catch(e){return null;} }
  function role(path,index) {
    if(/^\/(?:ar\/|en\/|fr\/)?$/.test(path))return 'home';
    if(/\/(?:contact|contact-us)\/?$/i.test(path))return 'contact';
    if(/\/(?:apartments|properties)\/?$/i.test(path))return 'property_catalog';
    if(/\/(?:apartments|properties)\/[^/]+\/?$/i.test(path))return 'property';
    if(/\/(?:availability|search)\/?$/i.test(path))return 'availability';
    return 'link_'+String(index);
  }
  function rewrite(raw,context,index) {
    const amp=raw.includes('&amp;');
    const original=raw.replace(/&amp;/g,'&');
    const m=original.match(/^(https?:\/\/)([^/?#]+)([^?#]*)(?:\?([^#]*))?(#.*)?$/i);
    if(!m)return {url:raw,exception:'unparseable'};
    const host=m[2].toLowerCase();
    if(![ROOT,'www.'+ROOT,ROOT+':443','www.'+ROOT+':443'].includes(host))return {url:raw,exception:'external'};
    const path=m[3]||'/';
