    const safePath=decode(path);
    if(safePath===null)return {url:raw,exception:'malformed_query'};
    if(/\/(?:media|static)(?:\/|$)/i.test(safePath)||/\.(?:png|jpe?g|gif|webp|svg|mp4|pdf|zip|css|js)$/i.test(safePath))return {url:raw,exception:'non_page_asset'};
    const parts=(m[4]||'').split('&').filter(Boolean);
    const parsed=parts.map(p=>{const pos=p.indexOf('=');const key=decode(pos<0?p:p.slice(0,pos));return {raw:p,key:key&&/^utm_/i.test(key)?key.toLowerCase():key,value:decode(pos<0?'':p.slice(pos+1))};});
    if(parsed.some(p=>p.key===null||p.value===null))return {url:raw,exception:'malformed_query'};
    if(/\/(?:api|webhook|payments?|checkout|accounts?|verify|verification|confirm|confirmation|reservations?|bookings?)(?:\/|$)/i.test(safePath)||parsed.some(p=>/^(?:.*token.*|.*signature.*|sig|auth|authorization|key|secret|email|phone|mobile|reservation_id|reservation_key|booking_id|booking_key|code|confirmation|nonce|session|access|ticket|hash)$/i.test(p.key)))return {url:raw,exception:'sensitive_or_signed'};
    const current={};
    for(const p of parsed)if(KEYS.includes(p.key)&&current[p.key]===undefined)current[p.key]=p.value;
    const channel=context.channel==='email'?'email':'whatsapp';
    const source=channel==='email'?'guest_email':'whatsapp',medium=channel==='email'?'email':'messaging';
    const campaign=current.utm_campaign||(String(context.scenario)==='05'?'missed_call':'guest_operations');
    const own=campaign==='guest_operations';
    const messageType=context.message_type||'';
    const s=origin(context.scenario,messageType);
    const lang=language(context.language,context.body);
    let content=current.utm_content;
    if(own){
      const saved=content&&content.match(/^(?:n8n_)?s(01|02|04|06)_((?:booking_confirmation|booking_cancellation|booking_modification|house_rules|checkin_guide|checkin_reminder|checkout_reminder|review_followup_[123]|message)_(?:home|contact|property_catalog|property|availability|link_[1-9][0-9]?))_(ar|en|fr)$/);
      content=saved?'n8n_s'+saved[1]+'_'+saved[2]+'_'+saved[3]:'n8n_s'+s+'_'+type(messageType)+'_'+role(path,index)+'_'+lang;
    }
    if(campaign==='missed_call'){content=current.utm_content||'scenario_05';}
    const wanted={utm_source:own?source:current.utm_source||source,utm_medium:own?medium:current.utm_medium||medium,utm_campaign:campaign,utm_content:content||'n8n_s'+s+'_'+type(messageType)+'_'+role(path,index)+'_'+lang};
    const ordinary=parsed.filter(p=>!KEYS.includes(p.key)).map(p=>p.raw);
    const tracked=[...ordinary,...KEYS.map(k=>k+'='+encodeURIComponent(wanted[k]))].join('&');
    const out=m[1]+m[2]+m[3]+'?'+tracked+(m[5]||'');
    return {url:amp?out.replace(/&/g,'&amp;'):out,exception:null};
  }
  function text(body,context={}) {
    const value=String(body??'');let index=0;
    return value.replace(/https?:\/\/[^\s<>"'\u200e\u200f\u202a-\u202e\u2066-\u2069]+/gi,match=>{
      let url=match,tail='';
      while(/[.,;!،؛。*`\]]$/.test(url)){tail=url.slice(-1)+tail;url=url.slice(0,-1);}
      while(url.endsWith(')')&&(url.match(/\)/g)||[]).length>(url.match(/\(/g)||[]).length){tail=')'+tail;url=url.slice(0,-1);}
