    for(const key of ['message_body','message_html','group_failure_body','group_success_body'])if(typeof out[key]==='string')out[key]=text(out[key],{...context,channel:key.startsWith('group_')?'whatsapp':context.channel});
    return out;
  }
  return {text,item,rewrite,language,origin};
}
