const LSA_TIME = (() => {
  const zones = new Set(['Asia/Riyadh', 'Africa/Casablanca']);
  // IANA tzdb 2026c: Morocco's September 20 change is 02:00 UTC+1 = 01:00Z.
  // The explicit rule bridges deployed Node/Intl versions with older tzdata.
  const change = Date.parse('2026-09-20T01:00:00Z');
  const parts = (input, zone) => {
    if (!zones.has(zone)) throw new Error('Unsupported property timezone: ' + zone);
    const instant = input instanceof Date ? input : new Date(input);
    if (!Number.isFinite(instant.getTime())) throw new Error('Invalid timestamp');
    const effective = zone === 'Africa/Casablanca' && instant.getTime() >= change ? 'UTC' : zone;
    return Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
      timeZone: effective, year:'numeric', month:'2-digit', day:'2-digit',
      hour:'2-digit', minute:'2-digit', second:'2-digit', hourCycle:'h23',
    }).formatToParts(instant).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));
  };
  const date = (input, zone) => {const p=parts(input,zone);return p.year+'-'+p.month+'-'+p.day;};
  const validDate = value => /^\d{4}-\d{2}-\d{2}$/.test(String(value||''))
    && Number.isFinite(Date.parse(value+'T12:00:00Z'))
    && new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value;
  const shift = (value, days) => {
    if(!validDate(value))throw new Error('Invalid property date');
    const instant=new Date(value+'T12:00:00Z');instant.setUTCDate(instant.getUTCDate()+days);
    return instant.toISOString().slice(0,10);
  };
  const normalizeTime = (value, fallback) => {
    const text=String(value??'').trim();
    if(/^\d{1,2}$/.test(text)&&Number(text)<24)return text.padStart(2,'0')+':00';
    if(/^([01]?\d|2[0-3]):[0-5]\d$/.test(text))return text.padStart(5,'0');
    return fallback;
  };
  const at = (day, time, zone) => {
    if(!zones.has(zone))throw new Error('Unsupported property timezone');
    if(!validDate(day))throw new Error('Invalid property date');
    const normalized=normalizeTime(time,'');if(!normalized)throw new Error('Invalid property time');
    const wall=Date.parse(day+'T'+normalized+':00Z');
    if(zone==='Africa/Casablanca'&&(day>'2026-09-20'||(day==='2026-09-20'&&normalized>='02:00')))return new Date(wall).toISOString();
    let utc=wall;
    for(let i=0;i<4;i++) {
      const p=parts(new Date(utc),zone);
      const shown=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second);
      const next=utc+(wall-shown);if(next===utc)break;utc=next;
    }
    return new Date(utc).toISOString();
  };
  return {parts,date,shift,at,normalizeTime,validDate,supported:zone=>zones.has(zone)};
})();

